import queue


def accepted(cap: int, xs: list[int]) -> int:
    """Count puts accepted by a bounded queue before it is full.

    Creates a queue holding at most `cap` integers and tries to put each
    element of `xs` in order without blocking. Stops at the first put
    that finds the queue full and returns the number of puts accepted
    up to that point. A capacity of zero or less accepts nothing.
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_accepted_stops_when_full() -> None:
    assert accepted(2, [1, 2, 3, 4]) == 2


def test_accepted_all_fit() -> None:
    assert accepted(5, [1, 2, 3]) == 3


def test_accepted_exact_capacity() -> None:
    assert accepted(3, [7, 8, 9]) == 3


def test_accepted_empty_input() -> None:
    assert accepted(4, []) == 0


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_accepted_negative_capacity() -> None:
    assert accepted(-1, [1, 2]) == 0


def test_accepted_duplicates_counted() -> None:
    assert accepted(3, [1, 1, 1, 1, 1]) == 3


def test_accepted_capacity_one() -> None:
    assert accepted(1, [10, 20]) == 1
